traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Firewall_Edge ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?alarmLabel
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?alarmLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?time WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?alarmType ?severity ?triggeredAt WHERE {
  net:Incident_DDoS net:composedOf ?rootAlarm .
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:alarmType ?alarmType ;
             net:hasSeverity ?severity ;
             net:triggeredAt ?triggeredAt .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCauseLabel WHERE {
  ?rootAlarm net:causallyLinkedTo+ net:Alarm_WebTimeout .
  ?rootAlarm net:alarmType ?type .
  ?rootAlarm rdfs:label ?rootCauseLabel .
} ORDER BY ?rootCauseLabel

PREFIX net: <http://example.org/network#>
SELECT ?causeLabel WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?cause .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label WHERE {
  <http://example.org/network#Alarm_FirewallSpike> net:causallyLinkedTo ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT ?intermediateAlarm WHERE {
  <http://example.org/network#Alarm_CPU> net:causallyLinkedTo* ?intermediateAlarm .
  FILTER(?intermediateAlarm = <http://example.org/network#Alarm_WebTimeout>)
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(?intermediate) AS ?pathExists) WHERE {
  net:Alarm_Latency net:causallyLinkedTo* net:Alarm_WebTimeout .
  OPTIONAL { net:Alarm_Latency net:causallyLinkedTo ?intermediate .
             ?intermediate net:causallyLinkedTo* net:Alarm_WebTimeout . }
}

PREFIX net: <http://example.org/network#>
SELECT ?device ?deviceLabel WHERE {
  ?alarm a net:Alarm .
  FILTER NOT EXISTS { ?cause net:causallyLinkedTo ?alarm . }
  ?alarm net:affectsDevice ?device .
  OPTIONAL { ?device rdfs:label ?deviceLabel . }
} LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  ?cause net:causallyLinkedTo ?effect .
  FILTER(?cause = net:Alarm_Latency && ?effect = net:Alarm_PacketDrop ||
         ?cause = net:Alarm_PacketDrop && ?effect = net:Alarm_Latency)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  net:Alarm_PacketDrop net:correlatedWith ?alarm .
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?device ?deviceLabel WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device ;
         rdfs:label ?alarmLabel .
  FILTER(CONTAINS(?alarmLabel, "R1"))
  FILTER NOT EXISTS {
    ?causeAlarm net:causallyLinkedTo ?alarm .
  }
  ?device rdfs:label ?deviceLabel .
} LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?affectedAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?affectedAlarm .
  ?affectedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?avoidedAlarm ?label WHERE {
  net:Alarm_CPU net:causallyLinkedTo ?avoidedAlarm .
  ?avoidedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?affectedAlarm) AS ?preventedAlarms)
WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo ?affectedAlarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?remainingAlarm ?alarmType ?severity
WHERE {
  # Incident and its alarms
  ?incident a net:Incident ;
            net:composedOf ?alarm .
  ?alarm net:alarmType ?alarmType ;
         net:hasSeverity ?severity .
  # Identify the CPU overload alarm
  BIND(net:Alarm_CPU AS ?cpuAlarm)
  # Exclude alarms that are causally linked from the CPU alarm
  FILTER NOT EXISTS {
    ?cpuAlarm net:causallyLinkedTo ?alarm .
  }
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?effect .
  FILTER(?effect = net:Alarm_WebTimeout)
  BIND(net:Alarm_Latency AS ?cause)
}
